#include <stdio.h>

int main(void) {
  int arr[5] = {10, 20, 30, 40, 50};
  int *p = arr;
  int sum = 0;

  for (int i = 0; i < 5; i++) {
    sum += *(p + i);
    if (i % 2 == 0) {
      arr[i] = arr[i] + i;
    }
  }

  for (int i = 0; i < 5; i++) {
    printf("%d ", arr[i]);
  }
  printf("\n");
  printf("sum = %d\n", sum);

  return 0;
}

public class Main {
  static class Animal {
    String name = "동물";

    void sound() { System.out.println(name + "이 소리를 낸다"); }

    void info() {
      System.out.println("이름: " + name);
      sound();
    }
  }

  static class Dog extends Animal {
    Dog() { name = "강아지"; }

    @Override
    void sound() {
      System.out.println(name + "이 멍멍 짖는다");
    }
  }

  public static void main(String[] args) {
    Animal a = new Animal();
    Animal d = new Dog();

    a.info();
    d.info();
  }
}

